$('pendingRows').addEventListener('input',e=>{const el=e.target;if(el.dataset.i===undefined)return;pending[Number(el.dataset.i)][el.dataset.k]=el.value});
$('discardPending').onclick=()=>{pending=[];renderPending()};$('importPending').onclick=()=>{const chosen=pending.filter(x=>x.selected);if(!chosen.length)return alert('Selecciona al menos una fila.');const invalid=chosen.find(x=>!valid(x));if(invalid)return alert('Hay filas seleccionadas sin sucursal, estilo, color, talla numérica o cantidad válida. Corrígelas.');let added=0,merged=0;for(const x of chosen){const i=duplicate(x);if(i>=0){if(!confirm(`Duplicado en ${x.sucursal}: ${x.estilo} / ${x.color} / ${x.talla}. ¿Sumar ${x.cantidad} unidad(es)?`))continue;items[i].cantidad=String(Number(items[i].cantidad||1)+Number(x.cantidad));items[i].saz_cargado=false;items[i].saz_cargado_at='';merged++}else{const {warning,selected,...record}=x;items.push(normalizeInventoryItem(record,'app_capture'));added++}}persist();pending=pending.filter(x=>!x.selected);renderPending();if(added+merged>0)clearCapturedPhotos();$('status').textContent=`Guardados ${added} nuevos; ${merged} acumulados. Todos los cambios quedaron pendientes de SAZ.${added+merged>0?' La captura quedó lista para el siguiente producto.':''}`};
function visionImageData(file){return createImageBitmap(file).then(bitmap=>{try{const maxSide=1800,scale=Math.min(1,maxSide/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);let quality=.86,data=canvas.toDataURL('image/jpeg',quality);while(data.length>3000000&&quality>.48){quality-=.1;data=canvas.toDataURL('image/jpeg',quality)}if(data.length>3500000)throw Error('La fotografía es demasiado grande para analizarla.');return data}finally{bitmap.close?.()}})}
