$('xlsx').onclick=()=>{if(!window.XLSX)return alert('No se cargó XLSX. Usa CSV.');const wb=XLSX.utils.book_new(),ws=XLSX.utils.json_to_sheet(data());ws['!cols']=[{wch:24},{wch:16},{wch:18},{wch:18},{wch:20},{wch:12},{wch:12},{wch:18},{wch:14},{wch:35},{wch:16},{wch:24},{wch:22}];XLSX.utils.book_append_sheet(wb,ws,'Inventario');XLSX.writeFile(wb,'CLAREMM_Inventario.xlsx')};
