const IMPORT_HEADERS={estilo:['estilo','style','codigo','codigoestilo','sku'],marca:['marca','brand'],sucursal:['sucursal','sucursales','branch','tienda','almacen','ubicacion'],color:['color'],linea:['linea','tipodelinea','tipolinea','line','categoria'],talla:['talla','size'],cantidad:['cantidad','quantity','qty','pares'],material:['material'],precio:['precio','price','valor'],notas:['notas','nota','notes','observaciones'],saz_cargado:['cargadoensaz','sazcargado','saz'],saz_cargado_at:['fechacargasaz','sazcargadoat'],origen:['origen','source','sourcesystem']};
function importHeader(value){return String(value??'').replace(/^\ufeff/,'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'')}
function importText(value){return String(value??'').trim()}
function normalizeImportRecord(source){const indexed={};for(const [key,value] of Object.entries(source||{}))indexed[importHeader(key)]=value;const record={};for(const field of fields){const alias=IMPORT_HEADERS[field]?.find(name=>Object.prototype.hasOwnProperty.call(indexed,name));record[field]=importText(alias?indexed[alias]:'')}if(!record.sucursal)record.sucursal=activeBranch();record.sucursal=record.sucursal.toUpperCase()==='MATRIZ'?DEFAULT_BRANCH:record.sucursal.toUpperCase();if(!record.cantidad)record.cantidad='1';record.talla=record.talla.replace(',','.');const statusAlias=IMPORT_HEADERS.saz_cargado.find(name=>Object.prototype.hasOwnProperty.call(indexed,name)),dateAlias=IMPORT_HEADERS.saz_cargado_at.find(name=>Object.prototype.hasOwnProperty.call(indexed,name)),originAlias=IMPORT_HEADERS.origen.find(name=>Object.prototype.hasOwnProperty.call(indexed,name));record.saz_cargado=importBoolean(statusAlias?indexed[statusAlias]:false);record.saz_cargado_at=record.saz_cargado?importText(dateAlias?indexed[dateAlias]:''):'';record.origen=importText(originAlias?indexed[originAlias]:'file_import')||'file_import';return record}
function importRowErrors(record){const errors=[];if(!record.sucursal)errors.push('falta sucursal');if(!record.estilo)errors.push('falta estilo');if(!record.color)errors.push('falta color');if(!record.talla||!Number.isFinite(Number(record.talla)))errors.push('talla inválida');const quantity=Number(record.cantidad);if(!Number.isInteger(quantity)||quantity<=0)errors.push('cantidad inválida');return errors}
function consolidateImportedRecords(records){const map=new Map;let duplicates=0;for(const record of records){const key=itemSyncKey(record);if(!map.has(key)){map.set(key,{...record});continue}const current=map.get(key);current.cantidad=String(Number(current.cantidad)+Number(record.cantidad));current.saz_cargado=false;current.saz_cargado_at='';for(const field of fields)if(field!=='cantidad'&&!current[field]&&record[field])current[field]=record[field];duplicates++}return {records:[...map.values()],duplicates}}
async function parseInventoryFile(file){const extension=file.name.split('.').pop()?.toLowerCase(),isJson=extension==='json'||file.type==='application/json';let rows;if(isJson){const parsed=JSON.parse(await file.text());rows=Array.isArray(parsed)?parsed:Array.isArray(parsed?.items)?parsed.items:Array.isArray(parsed?.records)?parsed.records:Array.isArray(parsed?.productos)?parsed.productos:null;if(!rows)throw Error('El JSON debe contener una lista de registros.')}else{if(!window.XLSX)throw Error('No se cargó el lector de Excel y CSV. Comprueba tu conexión.');const workbook=XLSX.read(await file.arrayBuffer(),{type:'array'}),sheet=workbook.Sheets[workbook.SheetNames[0]];if(!sheet)throw Error('El archivo no contiene una hoja legible.');rows=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:false})}if(!rows.length)throw Error('El archivo está vacío.');const recognizedHeaders=new Set(rows.slice(0,25).flatMap(row=>row&&typeof row==='object'?Object.keys(row).map(importHeader):[]));if(!Object.values(IMPORT_HEADERS).flat().some(header=>recognizedHeaders.has(header)))throw Error('No se reconocieron las columnas. Usa Sucursal, Estilo, Marca, Color, Tipo de línea, Talla, Cantidad, Material, Precio y Notas.');const validRecords=[],invalid=[];rows.forEach((row,index)=>{const rowNumber=index+(isJson?1:2);if(!row||typeof row!=='object'||Array.isArray(row)){invalid.push({row:rowNumber,reasons:['fila sin columnas']});return}const record=normalizeImportRecord(row),errors=importRowErrors(record);if(errors.length)invalid.push({row:rowNumber,reasons:errors});else validRecords.push(record)});const consolidated=consolidateImportedRecords(validRecords);return {fileName:file.name,sourceRows:rows.length,records:consolidated.records,duplicates:consolidated.duplicates,invalid}}
function updateImportAction(){const mode=document.querySelector('input[name="importMode"]:checked')?.value||'replace';$('importConfirm').textContent=mode==='replace'?'Reemplazar inventario':'Sumar al inventario'}
function showImportPreview(result){pendingBulkImport=result;const pairs=result.records.reduce((sum,item)=>sum+Number(item.cantidad),0),value=result.records.reduce((sum,item)=>sum+numericPrice(item.precio)*Number(item.cantidad),0);$('importFileName').textContent=result.fileName;$('importRecords').textContent=String(result.records.length);$('importPairs').textContent=String(pairs);$('importValue').textContent=new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(value);$('importInvalid').textContent=String(result.invalid.length);$('importSummary').textContent=`Se leyeron ${result.sourceRows} fila(s); actualmente tienes ${items.length} registro(s). ${result.duplicates?`${result.duplicates} duplicado(s) del archivo se consolidarán sumando cantidades.`:'No se detectaron duplicados por sucursal, estilo, color y talla.'}`;$('importErrors').hidden=!result.invalid.length;$('importErrorList').innerHTML=result.invalid.slice(0,50).map(error=>`<li>Fila ${error.row}: ${esc(error.reasons.join(', '))}</li>`).join('')+(result.invalid.length>50?`<li>Y ${result.invalid.length-50} fila(s) más.</li>`:'');document.querySelector('input[name="importMode"][value="replace"]').checked=true;$('importConfirm').disabled=!result.records.length;updateImportAction();if(!$('importDialog').open)$('importDialog').showModal()}
function closeImportDialog(){$('importDialog').close();pendingBulkImport=null;$('importFile').value=''}
$('importInventory').onclick=()=>$('importFile').click();
$('importFile').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;try{showImportPreview(await parseInventoryFile(file))}catch(error){event.target.value='';alert('No se pudo importar el archivo: '+error.message)}};
document.querySelectorAll('input[name="importMode"]').forEach(input=>input.addEventListener('change',updateImportAction));
$('importClose').onclick=closeImportDialog;$('importCancel').onclick=closeImportDialog;$('importDialog').addEventListener('cancel',event=>{event.preventDefault();closeImportDialog()});
$('importConfirm').onclick=()=>{if(!pendingBulkImport?.records.length)return;const mode=document.querySelector('input[name="importMode"]:checked')?.value||'replace',records=pendingBulkImport.records.map(item=>normalizeInventoryItem(item,'file_import')),previousCount=items.length;let added=0,merged=0;if(mode==='replace'){if(items.length){const timestamp=new Date().toISOString().replace(/[:.]/g,'-');download(new Blob([JSON.stringify(items,null,2)],{type:'application/json'}),`CLAREMM_Respaldo_antes_de_importar_${timestamp}.json`)}items=records;added=records.length}else{const positions=new Map(items.map((item,index)=>[itemSyncKey(item),index]));for(const record of records){const key=itemSyncKey(record),index=positions.get(key);if(index===undefined){positions.set(key,items.length);items.push(record);added++;continue}items[index].cantidad=String(Number(items[index].cantidad||1)+Number(record.cantidad));items[index].saz_cargado=false;items[index].saz_cargado_at='';for(const field of fields)if(field!=='cantidad'&&!items[index][field]&&record[field])items[index][field]=record[field];merged++}}inventoryQuery='';inventoryScope='all';inventorySazFilter='all';inventoryPage=1;$('inventorySearch').value='';$('inventorySearchScope').value='all';$('inventorySazFilter').value='all';persist();closeImportDialog();$('status').textContent=mode==='replace'?`Importación completa: ${added} registros reemplazaron los ${previousCount} anteriores.`:`Importación completa: ${added} nuevos y ${merged} acumulados; los acumulados volvieron a Pendiente de SAZ.`;$('inventoryResultInfo').scrollIntoView({behavior:'smooth',block:'center'})};
$('exportImages').onclick=async()=>{if(!window.JSZip)return alert('No se cargó el exportador ZIP. Comprueba internet.');const images=await listProductImages().catch(()=>[]);if(!images.length)return alert('No hay imágenes de producto guardadas.');const button=$('exportImages'),originalLabel=button.textContent;button.disabled=true;button.setAttribute('aria-busy','true');try{const zip=new JSZip;for(let i=0;i<images.length;i++){button.textContent=`Procesando ${i+1}/${images.length}`;$('imageExportInfo').textContent=`Verificando imagen ${i+1} de ${images.length}…`;const blob=await exportableImageBlob(images[i].blob);zip.file(images[i].name,blob)}button.textContent='Creando ZIP…';const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE',compressionOptions:{level:6}}),date=new Date().toISOString().slice(0,10);download(blob,`CLAREMM_Imagenes_${date}.zip`);$('imageExportInfo').textContent=`Exportadas ${images.length} imagen(es), cada una con máximo 100 KB.`}catch(e){$('imageExportInfo').textContent='No se pudo completar la exportación.';alert('No se pudieron exportar las imágenes: '+e.message)}finally{button.disabled=false;button.removeAttribute('aria-busy');button.textContent=originalLabel}};
let deferredInstallPrompt=null;const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true,isIOS=/iPad|iPhone|iPod/.test(navigator.userAgent),isMobile=isIOS||/Android/i.test(navigator.userAgent)||navigator.userAgentData?.mobile===true;
